/* estilo.css */
body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; }
h1 { color: #1f2937; }
a { color: #4f46e5; }

/*
  No F12 > Elements, clique duas vezes no hidden do input e troque por text.
  O campo aparece, com valor e tudo, e dá pra digitar outro.

  Prova: o HTML e o CSS que chegam no navegador são um rascunho editável.
  Quem manda no que vale é o servidor, sempre.
*/

exemplo.codigo:
const form = document.querySelector("#form");
const campo = document.querySelector("#senha");
const aviso = document.querySelector("#aviso");

form.addEventListener("submit", (evento) => {
  if (campo.value.length < 8) {
    evento.preventDefault();               // cancela o envio
    aviso.textContent = "Senha curta demais.";
  }
});

// textContent escreve texto. innerHTML escreveria HTML,
// e aí o que a pessoa digitasse viraria tag de verdade.
